// Interaction model from section 9: family -&gt; scope -&gt; measure -&gt; frequency
function familyPicker() {
  const scopesFor = f =&gt; ["national", "corporate", "industry"]
    .filter(sc =&gt; registry.some(r =&gt; r.chart_family === f && r.scope === sc));

  const btn = f =&gt; {
    // the structure product sits under Trend in the selector, so Trend stays lit
    const on = family === f || (f === "trend" && family === "income_structure");
    const el = html`&lt;button type="button" class="nisp-family-btn${on ? " selected" : ""}"
      aria-pressed="${on}"&gt;${familyLabels[f]}&lt;/button&gt;`;
    el.onclick = () =&gt; {
      mutable family = f;
      // Some families are industry-only, so move the scope with the family
      // rather than landing the reader on a state the registry does not declare
      const allowed = scopesFor(f);
      if (!allowed.includes(scope)) mutable scope = allowed[0];
    };
    return el;
  };
  return html`&lt;div class="nisp-family-list"&gt;
    &lt;span class="nisp-control-label"&gt;Chart family&lt;/span&gt;
    ${families.map(btn)}
  &lt;/div&gt;`;
}







function scopePicker() {
  const level = s =&gt; {
    const on = scope === s;
    const off = !scopesForFamily.includes(s);
    const el = html`&lt;button type="button" class="nisp-level-btn${on ? " selected" : ""}"
      aria-pressed="${on}" ${off ? "disabled" : ""}&gt;${scopeLabels[s]}&lt;/button&gt;`;
    el.onclick = () =&gt; { mutable scope = s; };
