// ---- Renderers -------------------------------------------------------
// Only these renderer_id values are implemented on the Website side. Rows
// whose renderer applies an analytical transformation belong to the chart
// workstream, so the page reports them as pending rather than implementing
// the economics here (contract sections 4.3 and 14.3).
websiteRenderers = ["income_structure_area", "timeseries_level_line",
  "timeseries_ratio_line", "cross_section_bar",
  "timeseries_growth_line", "historical_distribution_boxplot"]   // the last two plot values supplied in assets/data/charts/







function chartView() {
  if (!row) return html`&lt;p class="nisp-cat-empty"&gt;This combination is not a published
    EARL chart product.&lt;/p&gt;`;

  const ink = "#1f3347";
  const panel = document.querySelector(".nisp-ch-chart");
  const pageWidth = width;
  const w = Math.max(420, Math.round(panel ? panel.clientWidth : pageWidth) - 32);

  if (!websiteRenderers.includes(row.renderer_id)) {
    return html`&lt;div class="nisp-pending-chart"&gt;
      &lt;div class="nisp-ch-title"&gt;${chartTitle}&lt;/div&gt;
      &lt;p&gt;&lt;strong&gt;Awaiting chart renderer &lt;code&gt;${row.renderer_id}&lt;/code&gt;.&lt;/strong&gt;&lt;/p&gt;
      &lt;p&gt;This product applies the &lt;code&gt;${row.transformation_id}&lt;/code&gt; transformation,
      which belongs to the chart workstream. The Website will dispatch to the renderer
      once the registry row moves to &lt;em&gt;implemented&lt;/em&gt;; it does not compute the
      transformation itself.&lt;/p&gt;
      &lt;p class="nisp-control-note"&gt;Registry row ${row.chart_id} ·
      status ${row.production_status} · priority ${row.launch_priority}&lt;/p&gt;
    &lt;/div&gt;`;
  }

  // Cross-sectional bars at one common reference period
  if (row.renderer_id === "cross_section_bar") {
    if (!commonPeriod) return html`&lt;p class="nisp-cat-empty"&gt;No period is published for
      every peer industry on this measure, so there is no valid common reference period.&lt;/p&gt;`;
    const pct = isRatio(activeSeries);
    return html`&lt;div&gt;
      &lt;div class="nisp-ch-title"&gt;${chartTitle} · ${fmtPeriod(commonPeriod)}&lt;/div&gt;
      ${Plot.plot({
        width: w, height: 420, marginLeft: 190, marginRight: 24,
        x: {label: pct ? `${seriesLabel(activeSeries)} (%)` : `${seriesLabel(activeSeries)} ($ billions)`,
            labelArrow: "none", grid: true, tickFormat: pct ? ".0%" : ",.0f"},
        y: {label: null},
        marks: [
          Plot.barX(crossSectionRows, {y: "label", x: "v", fill: ink, sort: {y: "-x"}}),
          Plot.ruleX([0]),
          Plot.tip(crossSectionRows, Plot.pointerY({y: "label", x: "v",
            title: d =&gt; `${d.label}\n${seriesLabel(activeSeries)}: ${fmtValue(d.v, pct)}`}))
        ]
      })}
      &lt;p class="nisp-ch-note"&gt;All ${crossSectionRows.length} peer industries at the latest
      period published for every one of them. Parent aggregates are excluded.&lt;/p&gt;
    &lt;/div&gt;`;
  }

  // Income structure: the published components, stacked under the published total
  if (row.renderer_id === "income_structure_area") {
    const [totalId, ...partIds] = rowSeries;
    // The total can extend further back than the cost/revenue components
    // (National quarterly: GVA from 1947 but GO and II only from 2005).
    // Never render a missing stacked component as zero: use common valid coverage.
    const commonPeriods = periods.filter(p =&gt; valueAt(totalId, p) != null &&
      partIds.every(id =&gt; valueAt(id, p) != null));
    const parts = commonPeriods.flatMap(p =&gt; partIds.map(id =&gt;
      ({period: p, part: seriesLabel(id), v: valueAt(id, p)})));
    const total = commonPeriods.map(p =&gt; ({period: p, v: valueAt(totalId, p)}));
    if (!total.length) return html`&lt;p class="nisp-cat-empty"&gt;The Income Structure
      components are not simultaneously available for ${entityLabel} at this frequency.
      Individual published series may still be available in Trend.&lt;/p&gt;`;
    const coverageRestricted = commonPeriods.length &lt; periods.length;
    const partLabels = partIds.map(seriesLabel);
    return html`&lt;div&gt;
      &lt;div class="nisp-ch-title"&gt;${chartTitle}&lt;/div&gt;
      ${Plot.plot({
        width: w, height: 420, marginLeft: 76, marginRight: 24,
        x: timeAxis(commonPeriods, frequency, activeHistory, w),
        y: {label: "$ billions", labelArrow: "none", grid: true, tickFormat: ",.0f"},
        color: {domain: [partLabels[1], partLabels[0]],
                range: ["#8fb0c9", "#2f4a63"], legend: true},
        marks: [
          Plot.areaY(parts, {x: "period", y: "v", fill: "part",
            order: [partLabels[0], partLabels[1]], curve: "linear"}),
          Plot.lineY(total, {x: "period", y: "v", stroke: ink, strokeWidth: 1.5}),
          Plot.ruleY([0]),
          Plot.ruleX(total, Plot.pointerX({x: "period", stroke: ink, strokeOpacity: 0.35})),
          Plot.dot(total, Plot.pointerX({x: "period", y: "v", fill: ink, r: 3.5})),
          Plot.tip(total, Plot.pointerX({x: "period", y: "v",
            title: d =&gt; [fmtPeriod(d.period), `${seriesLabel(totalId)}: ${fmtValue(d.v)}`,
              ...partIds.map(id =&gt; `${seriesLabel(id)}: ${fmtValue(valueAt(id, d.period))}`)
            ].join("\n")}))
        ]
      })}
      &lt;p class="nisp-ch-note"&gt;${partLabels.join(" + ")} = ${seriesLabel(totalId)},
      as published. The line is the published total, not a sum computed here.
      ${coverageRestricted ? `The stacked structure starts at ${fmtPeriod(commonPeriods[0])},
      the first available period in this view with all components and the total; earlier
      individual observations remain available in Trend.` : ""}&lt;/p&gt;
    &lt;/div&gt;`;
  }

  // Growth and Distribution plot values supplied by the chart workstream (assets/data/charts/&lt;chart_id&gt;.json),
  // computed there with the chartbook's rules; the Website only selects, slices and formats them.
  if (chartDataRenderers.includes(row.renderer_id)) {
    if (!chartData) return html`&lt;p class="nisp-cat-empty"&gt;The values for this chart are not published.&lt;/p&gt;`;
    if (!chartDataCurrent) return html`&lt;p class="nisp-cat-empty"&gt;The values for this chart were built from a
      different data build than the one published, so they are not shown.&lt;/p&gt;`;
    const per = frequency === "annual" ? "year" : "quarter";
    const unit = chartData.value_unit;

    // Growth through time: one entity, one measure, gaps stay gaps
    if (row.renderer_id === "timeseries_growth_line") {
      const s = chartData.data?.[activeSeries]?.[activeEntity];
      const all = s ? s.periods.map((p, i) =&gt; ({period: p, v: s.values[i]})) : [];
      const pts = Number.isFinite(periodCount) ? all.slice(-periodCount) : all;
      const shown = pts.filter(d =&gt; d.v != null);
      if (!shown.length) return html`&lt;p class="nisp-cat-empty"&gt;${seriesLabel(activeSeries)} growth is not
        published for ${entityLabel} at this frequency.&lt;/p&gt;`;
      const [lo, hi] = d3.extent(shown, d =&gt; d.v);
      const tickPct = hi - lo &lt; 0.06 ? ".1%" : ".0%";    // a narrow range has ticks below one point: never round them into repeated labels
      return html`&lt;div&gt;
        &lt;div class="nisp-ch-title"&gt;${chartTitle}&lt;/div&gt;
        ${Plot.plot({
          width: w, height: 420, marginLeft: 76, marginRight: 24,
          x: timeAxis(pts.map(d =&gt; d.period), frequency, activeHistory, w),
          y: {label: `Change from previous ${per} (%)`, labelArrow: "none",
              grid: true, tickFormat: tickPct},
          marks: [
            Plot.ruleY([0]),
            Plot.lineY(pts, {x: "period", y: "v", stroke: ink, strokeWidth: 2}),
            Plot.ruleX(shown, Plot.pointerX({x: "period", stroke: ink, strokeOpacity: 0.35})),
            Plot.dot(shown, Plot.pointerX({x: "period", y: "v", fill: ink, r: 3.5})),
            Plot.tip(shown, Plot.pointerX({x: "period", y: "v",
              title: d =&gt; `${fmtPeriod(d.period)}\n${seriesLabel(activeSeries)} change: ${fmtChange(d.v)}`}))
          ]
        })}
        &lt;p class="nisp-ch-note"&gt;Change from the previous ${per}, computed by EARL from the published series.
        A period is left blank where the previous ${per} is missing or not positive and, for earnings measures,
        where its margin was below 1% of the top line, rather than showing a misleading figure.&lt;/p&gt;
      &lt;/div&gt;`;
    }

    // Distribution across industries: every observation, one box per industry, red X = most recent
    const d = chartData.data?.[activeSeries];
    if (!d) return html`&lt;p class="nisp-cat-empty"&gt;${seriesLabel(activeSeries)} is not published for the
      industry comparison.&lt;/p&gt;`;
    const nameOf = id =&gt; entityMeta.find(e =&gt; e.entity_id === id)?.entity_label ?? id;
    const lastIdx = Math.max(...d.order.map(id =&gt; { const p = d.sample[id].periods; return p.length ? periodIndex(p[p.length - 1]) : -Infinity; }));
    const firstIdx = Number.isFinite(periodCount) ? lastIdx - periodCount + 1 : -Infinity;
    const sample = d.order.flatMap(id =&gt; {
      const s = d.sample[id];
      const rows = s.periods.map((p, i) =&gt; ({label: nameOf(id), period: p, v: s.values[i], j: s.jitter[i]}))
        .filter(r =&gt; periodIndex(r.period) &gt;= firstIdx);
      if (rows.length) rows[rows.length - 1].latest = true;
      return rows;
    });
    if (!sample.length) return html`&lt;p class="nisp-cat-empty"&gt;No observations are published for this history.&lt;/p&gt;`;
    const latest = sample.filter(r =&gt; r.latest);
    const pctAxis = unit !== "points";
    const [xlo, xhi] = d3.extent(sample, r =&gt; r.v);
    const tickX = pctAxis ? (xhi - xlo &lt; 0.06 ? ".1%" : ".0%")
      : (d =&gt; d === 0 ? "0" : d3.format(xhi - xlo &lt; 6 ? "+.1f" : "+.0f")(d));
    // The supplied jitter (seeded, deterministic) spreads each industry's dots across its band. Plot's dy is one offset
    // per mark, so the dots are drawn in nine groups, one per offset.
    const jmax = d3.max(sample, r =&gt; Math.abs(r.j)) || 1;
    const jbin = r =&gt; Math.round(r.j / jmax * 4);
    // Decorative Tukey whisker caps. Use the same non-outlier convention
    // as Plot.boxX (1.5 * IQR); these do not transform the chart data.
    const whiskerCaps = d.order.flatMap(id =&gt; {
      const label = nameOf(id);
      const v = sample.filter(r =&gt; r.label === label && Number.isFinite(r.v))
        .map(r =&gt; r.v).sort(d3.ascending);
      if (!v.length) return [];
      const q1 = d3.quantileSorted(v, 0.25);
      const q3 = d3.quantileSorted(v, 0.75);
      const iqr = q3 - q1;
      const within = v.filter(x =&gt; x &gt;= q1 - 1.5 * iqr && x &lt;= q3 + 1.5 * iqr);
      return within.length ? [{label, v: within[0]}, {label, v: within[within.length - 1]}] : [];
    });
    return html`&lt;div&gt;
      &lt;div class="nisp-ch-title"&gt;${chartTitle}&lt;/div&gt;
      ${Plot.plot({
        width: w, height: 600, marginLeft: 190, marginRight: 24,
        x: {label: pctAxis ? `Change from previous ${per} (%)` : `Change from previous ${per} (percentage points)`,
            labelArrow: "none", grid: true, tickFormat: tickX},
        y: {label: null, domain: d.order.map(nameOf).reverse()},
        marks: [
          // Dashed neutral zero reference, visible without obscuring the boxes.
          Plot.ruleX([0], {stroke: "#61758a", strokeOpacity: 0.9,
            strokeWidth: 1.5, strokeDasharray: "5 4"}),
          ...d3.range(-4, 5).map(b =&gt; Plot.dot(sample.filter(r =&gt; jbin(r) === b),
            {x: "v", y: "label", dy: b * 1.7, r: 1.8, fill: "#8fb0c9", fillOpacity: 0.35})),
          // Filled IQR boxes and a stronger median distinguish the distribution
          // from the individual dots, including when its central spread is narrow.
          Plot.boxX(sample, {x: "v", y: "label", stroke: ink, strokeWidth: 1.8,
            fill: "#b3cede", fillOpacity: 0.88, r: 2}),
          Plot.tickX(whiskerCaps, {x: "v", y: "label", stroke: ink,
            strokeOpacity: 0.8, strokeWidth: 1.25, insetTop: 12, insetBottom: 12}),
          Plot.dot(latest, {x: "v", y: "label", symbol: "times", stroke: "#b03a2e", strokeWidth: 2.2, r: 7}),
          Plot.tip(sample, Plot.pointer({x: "v", y: "label",
            title: r =&gt; `${r.label}\n${fmtPeriod(r.period)}\n${seriesLabel(activeSeries)} change: ${fmtChange(r.v, unit)}${r.latest ? "\nMost recent observation" : ""}`}))
        ]
      })}
      &lt;p class="nisp-ch-note"&gt;Pale dots show each ${per}'s change; the filled box spans the
      middle 50% (interquartile range), its central mark is the median, and the red X is the latest observation.
      The dashed vertical line marks zero change; short end caps mark the non-outlier whiskers.
      Extreme observations remain included on the shared horizontal scale. Industries are ordered by
      ${seriesLabel(activeSeries)} in ${fmtPeriod(d.reference_period)}, the latest period published for all
      ${d.order.length} of them. Changes are computed by EARL from the published series.&lt;/p&gt;
    &lt;/div&gt;`;
  }

  // Single measure through time, level or ratio
  const pct = isRatio(activeSeries);
  const series = periods.map(p =&gt; ({period: p, v: valueAt(activeSeries, p)}))
    .filter(d =&gt; d.v != null);
  if (!series.length) return html`&lt;p class="nisp-cat-empty"&gt;${seriesLabel(activeSeries)} is
    not published for ${entityLabel} at this frequency.&lt;/p&gt;`;
  return html`&lt;div&gt;
    &lt;div class="nisp-ch-title"&gt;${chartTitle}&lt;/div&gt;
    ${Plot.plot({
      width: w, height: 420, marginLeft: 76, marginRight: 24,
      x: timeAxis(periods, frequency, activeHistory, w),
      y: {label: pct ? `${seriesLabel(activeSeries)} (%)` : "$ billions",
          labelArrow: "none", grid: true,
          tickFormat: pct ? ".0%" : ",.0f"},
      marks: [
        pct ? null : Plot.areaY(series, {x: "period", y: "v", fill: "#dce7f0"}),
        Plot.lineY(series, {x: "period", y: "v", stroke: ink, strokeWidth: 2}),
        Plot.ruleY([0]),
        Plot.ruleX(series, Plot.pointerX({x: "period", stroke: ink, strokeOpacity: 0.35})),
        Plot.dot(series, Plot.pointerX({x: "period", y: "v", fill: ink, r: 3.5})),
        Plot.tip(series, Plot.pointerX({x: "period", y: "v",
          title: d =&gt; `${fmtPeriod(d.period)}\n${seriesLabel(activeSeries)}: ${fmtValue(d.v, pct)}`}))
      ].filter(Boolean)
    })}
    &lt;p class="nisp-ch-note"&gt;${pct
      ? `${seriesLabel(activeSeries)} is shown as a percentage of its published denominator.`
      : `Dollar values are displayed in billions, scaled from the canonical published data.`}
      Earlier periods are shown only where the selected series is available.&lt;/p&gt;
  &lt;/div&gt;`;
}







function sourceNote() {
  if (!row) return html`&lt;div&gt;&lt;/div&gt;`;
  const shown = row.measure_mode === "select_one" ? [activeSeries] : rowSeries;
  const tables = new Map();
  for (const id of shown) {
    const meta = seriesMeta.find(s =&gt; s.dataset_id === row.dataset_id && s.series_id === id);
    if (meta?.source_dataset) {
      const key = meta.source_dataset;
      if (!tables.has(key)) tables.set(key, new Set());
      tables.get(key).add(meta.source_table_label || meta.source_table_id);
    }
  }
  return html`&lt;section class="nisp-provenance" aria-label="Data source and vintage"&gt;
    &lt;div class="nisp-provenance-head"&gt;
      &lt;strong&gt;Data source & vintage&lt;/strong&gt;
      &lt;span class="nisp-vintage-date"&gt;${vintage?.source_agency ?? "BEA"} · ${vintage?.source_release_date ?? "n/a"}&lt;/span&gt;
    &lt;/div&gt;
    &lt;p&gt;EARL preserves the documented source vintage for this chart. Newer BEA estimates
      may supersede some observations; this presentation retains the stated build for reproducibility.&lt;/p&gt;
    &lt;details class="nisp-source-details"&gt;
      &lt;summary&gt;BEA source tables, methodology & build details&lt;/summary&gt;
      &lt;div class="nisp-source-details-body"&gt;
        &lt;p&gt;&lt;strong&gt;Source release:&lt;/strong&gt; ${vintage?.source_release_name ?? "Not specified"}
          · ${vintage?.source_release_date ?? "n/a"}
          ${vintage?.source_release_url ? html` · &lt;a class="nisp-source-link"
            href="${vintage.source_release_url}" target="_blank" rel="noopener noreferrer"&gt;Archived BEA release notice&lt;/a&gt;` : ""}&lt;/p&gt;
        &lt;p&gt;&lt;strong&gt;Dataset:&lt;/strong&gt; ${row.dataset_id} ·
          &lt;strong&gt;Chart:&lt;/strong&gt; &lt;code&gt;${row.chart_id}&lt;/code&gt; ·
          &lt;strong&gt;Build:&lt;/strong&gt; &lt;code&gt;${build?.build_id ?? "n/a"}&lt;/code&gt;&lt;/p&gt;
        ${tables.size ? html`&lt;p&gt;&lt;strong&gt;Underlying BEA tables&lt;/strong&gt;&lt;/p&gt;
          &lt;ul class="nisp-source-tables"&gt;
            ${[...tables].map(([ds, t]) =&gt; html`&lt;li&gt;&lt;strong&gt;${ds}&lt;/strong&gt;: ${[...t].sort().join(", ")}&lt;/li&gt;`)}
          &lt;/ul&gt;` : ""}
        &lt;p&gt;${chartDataRenderers.includes(row.renderer_id)
          ? `Derived changes (${row.transformation_id}) use canonical data from the same build; the Website selects and formats the computed values.`
          : "Values come from the canonical published series; the Website filters and formats them without recalculating the economic data."}
          &lt;a class="nisp-source-link" href="method.html"&gt;Read EARL's methodology&lt;/a&gt;.&lt;/p&gt;
      &lt;/div&gt;
    &lt;/details&gt;
  &lt;/section&gt;`;
}

Validation & quality assurance
EARL validates both the underlying data and the public presentation.
Validation can include:

comparison with official source evidence;
verification of source mappings and metadata;
formula and accounting-identity checks;
expected-missingness checks;
historical-source and reconciliation checks;
statement and chart value checks;
review of labels, dates, units, scaling, sources, and rounding;
clean website and document rendering.

Validation documentation is retained so that the evidence supporting a published EARL release can be reviewed.
